    {
      "id": "r2",
      "type": "verse",
      "lines": [
        {
          "n": 1,
          "text": "द्वावेव ग्रसते दिनेश्वरनिशाप्राणेश्वरौ भासुरौ",
          "end": "line"
        },
        {
          "n": 2,
          "text": "भ्रातः पर्वणि पश्य दानवपतिः शीर्षावशेषीकृतः ॥ ३४ ॥",
          "end": "space"
        }
      ],
      "uncertain": false,
      "note": null
    },
    {
      "id": "r3",
      "type": "verse",
      "lines": [
        {
          "n": 1,
          "text": "वहति भुवनश्रेणीं शेषः फणाफलकस्थितां",
          "end": "line"
        },
        {
          "n": 2,
          "text": "कमठपतिना मध्येपृष्ठं सदा स विधार्यते ।",
          "end": "line"
        },
        {
          "n": 3,
          "text": "तमपि कुरुते क्रोडाधीनं पयोधिरनादरा-",
          "end": "hyphen"
        },
        {
          "n": 4,
          "text": "दहह महतां निःसीमानश्चरित्रविभूतयः ॥ ३५ ॥",
          "end": "space"
        }
      ],
      "uncertain": false,
      "note": null
    },
    {
      "id": "r4",
      "type": "verse",
      "lines": [
        {
          "n": 1,
          "text": "वरं पक्षच्छेदः समदमघवन्मुक्तकुलिश-",
          "end": "hyphen"
        },
        {
          "n": 2,
          "text": "प्रहारैरुद्गच्छद्बहलदहनोद्गारगुरुभिः ।",
          "end": "line"
        },
        {
          "n": 3,
          "text": "तुषाराद्रेः सूनोरहह पितरि क्लेशविवशे",
          "end": "line"
        },
        {
          "n": 4,
          "text": "न चासौ संपातः पयसि पयसां पत्युरुचितः ॥ ३६ ॥",
          "end": "space"
        }
      ],
      "uncertain": false,
      "note": null
    },
    {
      "id": "r5",
      "type": "verse",
      "lines": [
        {
          "n": 1,
          "text": "यदचेतनोपि पादैः स्पृष्टः प्रज्वलति सवितुरिनकान्तः ।",
          "end": "line"
        },
        {
          "n": 2,
          "text": "तत्तेजस्वी पुरुषः परकृतविकृतिं कथं सहते ॥ ३७ ॥",
          "end": "space"
        }
      ],
      "uncertain": false,
      "note": null
    },
    {
      "id": "r6",
      "type": "verse",
      "lines": [
        {
          "n": 1,
          "text": "सिंहः शिशुरपि निपतति मदमलिनकपोलभित्तिषु गजेषु ।",
          "end": "line"
        }
      ],
      "uncertain": false,
      "note": null
    },
